#include "TIM_LED.h"
#include "tim.h"

#define TIM_LED_TOGGLE_CYCLES 5U

/* TIM2 base initialization is generated by CubeMX into Core/Src/tim.c. */
void TIM_LED_Start(void)
{
  HAL_GPIO_WritePin(LED_GPIO_Port, LED_Pin, GPIO_PIN_RESET); /* Active low: LED on. */
  HAL_TIM_Base_Start_IT(&htim2);
}

/* TIM2 update interrupt callback. */
static uint8_t tim2_led_count = 0U;

void HAL_TIM_PeriodElapsedCallback(TIM_HandleTypeDef *htim)
{
  if (htim->Instance == TIM2)
  {
    if (++tim2_led_count >= TIM_LED_TOGGLE_CYCLES)
    {
      tim2_led_count = 0U;
      HAL_GPIO_TogglePin(LED_GPIO_Port, LED_Pin);
    }
  }
}
